// DocumentReviewStats: 每个等待状态的实体数和最老的进入时间(指标: factory_sm_instances / factory_sm_oldest_in_state_seconds)。
func (h *Handler) DocumentReviewStats(ctx context.Context, q sm.Querier) ([]sm.StateStat, error) {
	names := map[int32]string{1: "REVIEWING", 2: "PUBLISHING"}
	by := map[string]sm.StateStat{}
	rows, err := q.Query(ctx, "SELECT \"status\", count(*), min(\"entered_at\") FROM \"documents\" WHERE \"status\" IN (1, 2) GROUP BY \"status\"")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var s int32
		var x sm.StateStat
		if err := rows.Scan(&s, &x.Count, &x.Oldest); err != nil {
			return nil, err
		}
		x.State = names[s]
		by[x.State] = x
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	var out []sm.StateStat
	for _, n := range []string{"REVIEWING", "PUBLISHING"} {
		x := by[n]
		x.State = n
		out = append(out, x)
	}
	return out, nil
}
